1.3 3 Document Processing Pipeline

1.3.1 3.1 Document Loaders
class DocumentLoader:
    """
    Multi-format document loader for research materials.
    Supports: PDF, DOCX, XLSX, CSV, TXT, MD
    """

    def __init__(self, base_paths: List[str]):
        self.base_paths = [Path(p) for p in base_paths]

    def _load_pdf(self, file_path: Path) -&gt; str:
        try:
            reader = PdfReader(str(file_path))
            texts = []
            for page in reader.pages:
                text = page.extract_text()
                if text:
                    texts.append(text)
            return " ".join(texts)
        except:
            return ""

    def _load_docx(self, file_path: Path) -&gt; str:
        try:
            doc = DocxDocument(str(file_path))
            paragraphs = [p.text for p in doc.paragraphs if p.text.strip()]
            return "\n\n".join(paragraphs)
        except:
            return ""

    def _load_excel(self, file_path: Path) -&gt; str:
        try:
            df = pd.read_excel(file_path)
            return df.to_string(index=False)
        except:
            return ""

    def scan(self) -&gt; List[Dict[str, Any]]:
        loaders = {
            '.pdf': self._load_pdf,
            '.docx': self._load_docx,
            '.xlsx': self._load_excel,
        }

        documents = []
        for base in self.base_paths:
            if not Path(base).exists():
                continue
            for f in Path(base).rglob("*"):
                if f.is_file() and f.suffix.lower() in loaders:
                    content = loaders[f.suffix.lower()](f)
                    if content:
                        documents.append({
                            'content': content,
                            'filename': f.name
                        })
        return documents


1.3.2 3.2 Text Chunking
class TextChunker:
    """Intelligent text chunking with overlap for context preservation."""

    def __init__(self, chunk_size: int = 800, chunk_overlap: int = 100):
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap

    def chunk(self, documents: List[Dict]) -&gt; List[Dict]:
        chunks = []
        for doc in documents:
            text = doc['content']
            start = 0
            idx = 0
            while start &lt; len(text):
                chunk_text = text[start:start + self.chunk_size]
                if chunk_text.strip():
                    chunks.append({
                        'content': chunk_text,
                        'filename': doc['filename'],
                        'chunk_id': idx
                    })
                    idx += 1
                start += self.chunk_size - self.chunk_overlap
        return chunks

3.4 Group 3: Markov-Switching GARCH
The MS-GARCH(1,1) model with \(K=2\) regimes specifies (Haas, Mittnik, and Paolella 2004; Ardia et al. 2019):
\[
\begin{aligned}
r_t &= \mu_{s_t} + \epsilon_t, \quad \epsilon_t = \sigma_t z_t, \quad z_t \sim D(0,1,\nu_{s_t}) \\
\sigma_t^2 &= \omega_{s_t} + \alpha_{s_t} \epsilon_{t-1}^2 + \beta_{s_t} \sigma_{t-1}^2 \\
P(s_t = j | s_{t-1} = i) &= p_{ij}
\end{aligned}
\]
where \(s_t \in \{1,2\}\) is the latent regime, \(D\) is a flexible distribution (Student-t, GED), and \(p_{ij}\) are transition probabilities. Filtered regime probabilities \(\xi_{t|t}(j) = P(s_t = j | \mathcal{F}_t)\) are computed via the Hamilton filter.
